11	        inputSchema: {
12	          type: 'object',
13	          properties: {channel: {type: 'string'}},
14	          required: ['channel'],
15	        },
16	      },
17	      async () => {
18	        executorRuns += 1;
19	        return 'sent';
20	      }
21	    );
22	
23	    const rejection = await registry.execute('send_alert', {});
24	
25	    expect({
26	      executorRuns,
27	      namesChannel: rejection.result.includes('channel'),
28	      saysRequired: /required/i.test(rejection.result),
29	    }).toEqual({executorRuns: 0, namesChannel: true, saysRequired: true});
30	  });
31	
